mapper.select:
SELECT s.std_val::integer FROM TB_SY_OPER_STD s WHERE s.std_cd=#{code}
  AND s.aply_bgn_ym <= to_char(clock_timestamp() AT TIME ZONE 'Asia/Seoul','YYYYMM')
ORDER BY s.aply_bgn_ym DESC LIMIT 1

SELECT EXISTS (SELECT 1 FROM TB_PJ_PROJ_PART h WHERE h.proj_id=#{projectId}
  AND h.aply_bgn_ym=COALESCE((SELECT max(x.aply_bgn_ym) FROM TB_PJ_PROJ_PART x WHERE x.proj_id=#{projectId}
      AND x.aply_bgn_ym <= to_char(clock_timestamp() AT TIME ZONE 'Asia/Seoul','YYYYMM')),
    (SELECT min(x.aply_bgn_ym) FROM TB_PJ_PROJ_PART x WHERE x.proj_id=#{projectId}))
  AND h.part_id IN #{part})

mapper.update:
UPDATE TB_SY_USER SET pwd_err_cnt=LEAST(pwd_err_cnt+1,99),
  user_stat_cd=CASE WHEN pwd_err_cnt+1 >= #{threshold} THEN 'LOCK' ELSE user_stat_cd END
WHERE user_id=#{id}


WITH cleared_period AS (DELETE FROM TB_SY_USER_PREF WHERE user_id=#{id} AND pref_type_cd='PERIOD')
UPDATE TB_SY_USER SET pwd_err_cnt=0,mfa_err_cnt=0,last_login_dttm=#{now},
  mfa_code_hash=NULL,mfa_expr_dttm=NULL WHERE user_id=#{id}
